CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS demo_sessions (id TEXT PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ NOT NULL DEFAULT now()+interval '30 days');
CREATE TABLE IF NOT EXISTS customers (customer_id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, fictional BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS accounts (account_id TEXT PRIMARY KEY, customer_id TEXT NOT NULL UNIQUE REFERENCES customers, restrictions TEXT[] NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS subscriptions (subscription_id TEXT PRIMARY KEY, account_id TEXT NOT NULL UNIQUE REFERENCES accounts, tier TEXT NOT NULL CHECK(tier IN ('Free','Pro','Business','Enterprise')), status TEXT NOT NULL, billing_cycle TEXT NOT NULL, started_on DATE NOT NULL);
CREATE TABLE IF NOT EXISTS contracts (contract_id TEXT PRIMARY KEY, account_id TEXT NOT NULL UNIQUE REFERENCES accounts, status TEXT NOT NULL, starts_on DATE NOT NULL, ends_on DATE);
CREATE TABLE IF NOT EXISTS invoices (invoice_id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers, account_id TEXT NOT NULL REFERENCES accounts, subscription_id TEXT NOT NULL REFERENCES subscriptions, contract_id TEXT NOT NULL REFERENCES contracts, date DATE NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), currency TEXT NOT NULL DEFAULT 'USD', status TEXT NOT NULL, description TEXT NOT NULL, billing_cycle TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chats (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES demo_sessions, title TEXT NOT NULL DEFAULT 'New chat', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), escalation JSONB);
CREATE TABLE IF NOT EXISTS messages (id BIGSERIAL PRIMARY KEY, chat_id TEXT NOT NULL REFERENCES chats, role TEXT NOT NULL, content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS verified_customers (chat_id TEXT PRIMARY KEY REFERENCES chats, customer_id TEXT NOT NULL REFERENCES customers);
CREATE TABLE IF NOT EXISTS refund_pending (token TEXT PRIMARY KEY, chat_id TEXT NOT NULL REFERENCES chats, customer_id TEXT NOT NULL REFERENCES customers, invoice_id TEXT NOT NULL REFERENCES invoices, amount_cents INTEGER NOT NULL, policy_version INTEGER NOT NULL, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS refund_receipts (receipt_id TEXT PRIMARY KEY, confirmation_token TEXT NOT NULL UNIQUE, invoice_id TEXT NOT NULL UNIQUE REFERENCES invoices, customer_id TEXT NOT NULL REFERENCES customers, amount_cents INTEGER NOT NULL, policy_version INTEGER NOT NULL, chat_id TEXT NOT NULL REFERENCES chats, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS escalation_tickets (ticket_id TEXT PRIMARY KEY, chat_id TEXT NOT NULL REFERENCES chats, customer_id TEXT NOT NULL REFERENCES customers, category TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', context JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_open_ticket_per_chat ON escalation_tickets(chat_id) WHERE status='open';
CREATE TABLE IF NOT EXISTS voice_requests (chat_id TEXT NOT NULL REFERENCES chats, call_id TEXT NOT NULL, status TEXT NOT NULL, answer TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(chat_id,call_id));
CREATE TABLE IF NOT EXISTS turn_requests (chat_id TEXT NOT NULL REFERENCES chats, request_id TEXT NOT NULL, status TEXT NOT NULL, answer TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(chat_id, request_id));
CREATE TABLE IF NOT EXISTS traces (trace_id TEXT PRIMARY KEY, chat_id TEXT NOT NULL REFERENCES chats, events JSONB NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS knowledge_chunks (chunk_id TEXT PRIMARY KEY, document_id TEXT NOT NULL, title TEXT NOT NULL, document_type TEXT NOT NULL, version INTEGER NOT NULL, tiers TEXT[] NOT NULL, effective_date DATE NOT NULL, expiration_date DATE, active BOOLEAN NOT NULL, section TEXT NOT NULL, source_reference TEXT NOT NULL, content TEXT NOT NULL, content_hash TEXT NOT NULL, embedding_model TEXT NOT NULL, embedding vector(768) NOT NULL);
CREATE INDEX IF NOT EXISTS knowledge_metadata_idx ON knowledge_chunks(document_id,active);
CREATE TABLE IF NOT EXISTS refund_rules (tier TEXT NOT NULL, version INTEGER NOT NULL, active BOOLEAN NOT NULL, effective_date DATE NOT NULL, expiration_date DATE, window_days INTEGER NOT NULL, max_amount_cents INTEGER NOT NULL, billing_cycles TEXT[] NOT NULL, manual_review BOOLEAN NOT NULL DEFAULT FALSE, document_id TEXT NOT NULL, PRIMARY KEY(tier,version));
CREATE INDEX IF NOT EXISTS messages_chat_idx ON messages(chat_id,id);
CREATE INDEX IF NOT EXISTS chats_session_idx ON chats(session_id,created_at);
